import {commentInput,relationInput} from '../../../shared/src/schemas/discussion.js';
import {readFile} from 'node:fs/promises';
import {query} from '../client.js';
import {issueInput,labelInput} from '../../../shared/src/schemas/issue.js';
export const ISSUE_USAGE=`crew issue list PROJECT [--status ID] [--assignee ID] [--label ID] [--priority N] [--query TEXT]
crew issue create PROJECT --title TEXT [--description TEXT] [--status ID] [--priority N] [--assignee ID] [--estimate N] [--due YYYY-MM-DD] [--parent ID] [--labels ID,ID]
crew issue show ISSUE | edit ISSUE [fields] | delete ISSUE
crew issue labels PROJECT | label-create PROJECT --name TEXT [--color '#abcdef']
crew issue label-edit LABEL [--name TEXT] [--color COLOR] | label-delete LABEL
crew issue comments ISSUE | comment ISSUE --body TEXT [--body-file FILE]
crew issue comment-edit COMMENT --body TEXT | comment-delete COMMENT --yes
crew issue relations ISSUE | relate ISSUE --target ISSUE --kind blocks|duplicates|relates
crew issue unrelate RELATION --yes`;
function required(value,name){if(!value)throw new Error('Missing '+name+'\n'+ISSUE_USAGE);return value;}
export async function issueOptions(options,{partial=false}={}) {
  const body={};
  const mapping={title:'title',description:'description',status:'statusId',priority:'priority',assignee:'assigneeId',estimate:'estimate',due:'dueDate',parent:'parentId'};
  for(const [option,field] of Object.entries(mapping))if(Object.hasOwn(options,option))body[field]=['assignee','parent','due','estimate'].includes(option)&&options[option]==='none'?null:options[option];
  if(options['description-file'])body.description=await readFile(options['description-file'],'utf8');
  if(Object.hasOwn(options,'labels'))body.labelIds=options.labels==='none'?[]:String(options.labels).split(',').map(value=>value.trim()).filter(Boolean);
  return issueInput(body,{partial});
}
export async function issueCommand({args,options,client,print}) {
  const [action='list',id]=args;
  if(action==='help'){print(ISSUE_USAGE);return;}
  required(id,action==='list'||action==='create'||action==='labels'||action==='label-create'?'project id':'issue or label id');
  if(action==='list'){print(await client.get('/projects/'+encodeURIComponent(id)+'/issues'+query({statusId:options.status,assigneeId:options.assignee,labelId:options.label,priority:options.priority,q:options.query,limit:options.limit,cursor:options.cursor})));return;}
  if(action==='show'){print(await client.get('/issues/'+encodeURIComponent(id)));return;}
  if(action==='create'){print(await client.post('/projects/'+encodeURIComponent(id)+'/issues',await issueOptions(options)));return;}
  if(action==='edit'){print(await client.patch('/issues/'+encodeURIComponent(id),await issueOptions(options,{partial:true})));return;}
  if(action==='delete'){
    if(!options.yes)throw new Error('Use --yes to delete an issue');
    print(await client.delete('/issues/'+encodeURIComponent(id)));return;
  }
  if(action==='labels'){print(await client.get('/projects/'+encodeURIComponent(id)+'/labels'+query({limit:options.limit,cursor:options.cursor})));return;}
  if(action==='label-create'){print(await client.post('/projects/'+encodeURIComponent(id)+'/labels',labelInput({name:options.name,color:options.color})));return;}
  if(action==='label-edit'){
    const body={};for(const field of ['name','color'])if(options[field]!==undefined)body[field]=options[field];
    print(await client.patch('/labels/'+encodeURIComponent(id),labelInput(body,{partial:true})));return;
  }
  if(action==='label-delete'){
    if(!options.yes)throw new Error('Use --yes to delete a label');
    print(await client.delete('/labels/'+encodeURIComponent(id)));return;
  }
  if(action==='comments'){print(await client.get('/issues/'+encodeURIComponent(id)+'/comments'+query({limit:options.limit,cursor:options.cursor})));return;}
  if(action==='comment'||action==='comment-edit'){
    const body=options['body-file']?await readFile(options['body-file'],'utf8'):options.body;
    const input=commentInput({body});
    print(action==='comment'?await client.post('/issues/'+encodeURIComponent(id)+'/comments',input):await client.patch('/comments/'+encodeURIComponent(id),input));return;
  }
  if(action==='comment-delete'){
    if(!options.yes)throw new Error('Use --yes to delete a comment');
    print(await client.delete('/comments/'+encodeURIComponent(id)));return;
  }
  if(action==='relations'){print(await client.get('/issues/'+encodeURIComponent(id)+'/relations'+query({limit:options.limit,cursor:options.cursor})));return;}
  if(action==='relate'){print(await client.post('/issues/'+encodeURIComponent(id)+'/relations',relationInput({targetIssueId:options.target,kind:options.kind})));return;}
  if(action==='unrelate'){
    if(!options.yes)throw new Error('Use --yes to remove a relation');
    print(await client.delete('/relations/'+encodeURIComponent(id)));return;
  }
  throw new Error('Unknown issue action: '+action+'\n'+ISSUE_USAGE);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
async function scenario(fn) {
  const server=await testServer();
  try{
    const api=server.agent();const auth=await api('POST','/auth/signup',{name:'Owner',email:'owner@example.test',password:'correct-horse-battery'});
    const org=(await api('POST','/orgs',{name:'Discussion'})).data.organization;
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'DIS',name:'Discussion'})).data.project;
    const create=async title=>(await api('POST','/projects/'+project.id+'/issues',{title})).data.issue;
    const issue=await create('Discuss');
    await fn({server,api,user:auth.data.user,org,project,issue,create});
  }finally{await server.close();}
}
test('comments store markdown safely resolve visible mentions and emit notification identity',()=>scenario(async({server,api,user,issue})=>{
  const events=[];server.ctx.bus.subscribe(event=>events.push(event));
  const body='Hello @[Owner](user:'+user.id+') <script>bad</script> **strong**';
  const result=await api('POST','/issues/'+issue.id+'/comments',{body});
  assert.equal(result.status,201);const comment=result.data.comment;
  assert.equal(comment.body,body);assert.deepEqual(comment.mentionedUserIds,[user.id]);assert.ok(comment.html.includes('&lt;script&gt;'));assert.ok(comment.html.includes('<strong>strong</strong>'));assert.equal(comment.author.name,'Owner');
  const event=events.find(event=>event.entityType==='comment');assert.equal(event.after.issue.id,issue.id);assert.deepEqual(event.after.mentionedUserIds,[user.id]);assert.equal(event.after.issue.createdBy,user.id);
  assert.equal((await api('GET','/issues/'+issue.id+'/comments')).data.items[0].body,body);
}));
test('comment edits and deletion enforce author or administrator while granted guests can comment',()=>scenario(async({server,api,org,project,issue})=>{
  const guest=server.agent();const auth=await guest('POST','/auth/signup',{name:'Guest',email:'guest@example.test',password:'correct-horse-battery'});
  await api('POST','/orgs/'+org.id+'/members',{userId:auth.data.user.id,role:'guest'});await api('POST','/projects/'+project.id+'/guests',{userId:auth.data.user.id});
  const ownerComment=(await api('POST','/issues/'+issue.id+'/comments',{body:'Owner comment'})).data.comment;
  assert.equal((await guest('PATCH','/comments/'+ownerComment.id,{body:'No'})).status,403);
  const own=(await guest('POST','/issues/'+issue.id+'/comments',{body:'Guest comment'})).data.comment;
  assert.equal((await guest('PATCH','/comments/'+own.id,{body:'Guest edit'})).status,200);
  assert.equal((await api('DELETE','/comments/'+own.id)).status,200);
  assert.equal((await api('GET','/issues/'+issue.id+'/comments')).data.items.length,1);
}));
test('mentions ignore code and people without access to the project',()=>scenario(async({server,api,org,issue})=>{
  const outsider=server.agent();const auth=await outsider('POST','/auth/signup',{name:'Outside',email:'outside@example.test',password:'correct-horse-battery'});
  await api('POST','/orgs/'+org.id+'/members',{userId:auth.data.user.id,role:'guest'});
  const comment=(await api('POST','/issues/'+issue.id+'/comments',{body:'@[Outside](user:'+auth.data.user.id+') `@owner`'})).data.comment;
  assert.deepEqual(comment.mentionedUserIds,[]);
}));
test('comment cursors are stable and whitespace-only writes return field errors',()=>scenario(async({api,issue})=>{
  assert.equal((await api('POST','/issues/'+issue.id+'/comments',{body:'  '})).status,422);
  await api('POST','/issues/'+issue.id+'/comments',{body:'First'});await api('POST','/issues/'+issue.id+'/comments',{body:'Second'});
  const page=(await api('GET','/issues/'+issue.id+'/comments?limit=1')).data;
  assert.equal(page.items[0].body,'First');assert.ok(page.nextCursor);
  assert.equal((await api('GET','/issues/'+issue.id+'/comments?cursor='+page.nextCursor)).data.items[0].body,'Second');
}));
test('all relation kinds expose correct incoming outgoing and symmetric meanings',()=>scenario(async({api,issue,create})=>{
  for(const kind of ['blocks','duplicates','relates']){
    const target=await create('Target '+kind);
    const result=await api('POST','/issues/'+issue.id+'/relations',{kind,targetIssueId:target.id});assert.equal(result.status,201);
    const from=(await api('GET','/issues/'+issue.id+'/relations')).data.items.find(item=>item.id===result.data.relation.id);
    const to=(await api('GET','/issues/'+target.id+'/relations')).data.items[0];
    assert.equal(from.direction,kind==='relates'?'both':'outgoing');assert.equal(to.direction,kind==='relates'?'both':'incoming');assert.equal(to.relatedIssue.id,issue.id);
    assert.equal(to.caption,kind==='blocks'?'blocked by':kind==='duplicates'?'duplicated by':'relates to');
  }
}));
test('relation duplicate reverse symmetric self and directed cycles are rejected',()=>scenario(async({api,issue,create})=>{
  const target=await create('Target'),third=await create('Third');
  assert.equal((await api('POST','/issues/'+issue.id+'/relations',{kind:'relates',targetIssueId:issue.id})).status,422);
  await api('POST','/issues/'+issue.id+'/relations',{kind:'relates',targetIssueId:target.id});
  assert.equal((await api('POST','/issues/'+target.id+'/relations',{kind:'relates',targetIssueId:issue.id})).status,409);
  await api('POST','/issues/'+issue.id+'/relations',{kind:'blocks',targetIssueId:target.id});
  await api('POST','/issues/'+target.id+'/relations',{kind:'blocks',targetIssueId:third.id});
  assert.equal((await api('POST','/issues/'+third.id+'/relations',{kind:'blocks',targetIssueId:issue.id})).status,422);
  await api('POST','/issues/'+issue.id+'/relations',{kind:'duplicates',targetIssueId:third.id});
  assert.equal((await api('POST','/issues/'+issue.id+'/relations',{kind:'duplicates',targetIssueId:target.id})).status,409);
}));
test('relations hide inaccessible targets before pagination and require both write permissions',()=>scenario(async({server,api,org,project,issue})=>{
  const other=(await api('POST','/orgs/'+org.id+'/projects',{key:'HID',name:'Hidden'})).data.project;
  const hidden=(await api('POST','/projects/'+other.id+'/issues',{title:'Hidden'})).data.issue;
  const relation=(await api('POST','/issues/'+issue.id+'/relations',{kind:'relates',targetIssueId:hidden.id})).data.relation;
  const guest=server.agent();const auth=await guest('POST','/auth/signup',{name:'Guest',email:'guest@example.test',password:'correct-horse-battery'});
  await api('POST','/orgs/'+org.id+'/members',{userId:auth.data.user.id,role:'guest'});await api('POST','/projects/'+project.id+'/guests',{userId:auth.data.user.id});
  const page=(await guest('GET','/issues/'+issue.id+'/relations?limit=1')).data;assert.deepEqual(page.items,[]);assert.equal(page.nextCursor,null);
  assert.equal((await guest('POST','/issues/'+issue.id+'/relations',{kind:'blocks',targetIssueId:hidden.id})).status,403);
  assert.equal((await api('DELETE','/relations/'+relation.id)).status,200);assert.deepEqual((await api('GET','/issues/'+issue.id+'/relations')).data.items,[]);
}));
test('issue deletion cascades discussion and relation storage',()=>scenario(async({server,api,issue,create})=>{
  const target=await create('Target');await api('POST','/issues/'+issue.id+'/comments',{body:'Gone'});await api('POST','/issues/'+issue.id+'/relations',{kind:'blocks',targetIssueId:target.id});await api('DELETE','/issues/'+issue.id);
  assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM comments').get().n,0);assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM issue_relations').get().n,0);
}));

import test from 'node:test';
import assert from 'node:assert/strict';
import {renderMarkdown,extractMentions,safeMarkdownUrl} from '../src/markdown.js';
import {relationPair,relationCaption,commentInput} from '../src/schemas/discussion.js';
test('markdown escapes raw HTML and every attribute delimiter',()=>{
  const html=renderMarkdown('<script>alert("x")</script> <img src=x onerror=alert(1)>');
  assert.ok(html.includes('&lt;script&gt;'));assert.ok(html.includes('&quot;x&quot;'));assert.equal(html.includes('<script>'),false);assert.equal(html.includes('<img '),false);
});
test('markdown permits safe links and rejects executable schemes',()=>{
  assert.ok(renderMarkdown('[Docs](https://example.test/path?a=1&b=2)').includes('href="https://example.test/path?a=1&amp;b=2"'));
  for(const url of ['javascript:alert','data:text/html,bad','file:///tmp/a','https:\n//evil'])assert.equal(safeMarkdownUrl(url),null);
  assert.equal(renderMarkdown('[Bad](javascript:alert)').includes('<a '),false);
});
test('markdown renders headings strong emphasis lists quotes and tasks',()=>{
  const html=renderMarkdown('# Heading\n\n**Bold** and *emphasis*\n\n- [x] Done\n- Open\n\n> Quote');
  for(const expected of ['<h1>Heading</h1>','<strong>Bold</strong>','<em>emphasis</em>','<ul>','disabled checked','<blockquote>'])assert.ok(html.includes(expected),expected);
});
test('markdown code remains literal and does not mention or format',()=>{
  const result=renderMarkdown('`**literal** @nobody`\n\n```js\n<script> @owner\n```');
  assert.ok(result.includes('<code>**literal** @nobody</code>'));assert.ok(result.includes('&lt;script&gt; @owner'));assert.deepEqual(extractMentions('`@owner`\n```\n@guest\n```'),[]);
});
test('markdown supports canonical readable id and email mentions with deduplication',()=>{
  assert.deepEqual(extractMentions('@[Alice Doe](user:USER-1) @{USER-2} @alice @alice @alice@example.test'),['user-1','user-2','alice','alice@example.test']);
  assert.ok(renderMarkdown('@[<Alice>](user:user-1)').includes('@&lt;Alice&gt;'));
});
test('markdown mention boundaries avoid email and escaped false positives',()=>{assert.deepEqual(extractMentions('name@example.test \\@owner @actual'),['actual']);});
test('markdown unclosed code fences escape content until end safely',()=>{const html=renderMarkdown('```\n<b> text');assert.equal(html,'<pre><code>&lt;b&gt; text</code></pre>');});
test('relates is symmetric while blocks and duplicates retain source direction',()=>{
  assert.deepEqual(relationPair('z','a','relates'),['a','z']);assert.deepEqual(relationPair('z','a','blocks'),['z','a']);assert.deepEqual(relationPair('z','a','duplicates'),['z','a']);
  assert.throws(()=>relationPair('x','x','blocks'),{code:'VALIDATION'});
});
test('relation captions distinguish both directed inverse meanings',()=>{assert.equal(relationCaption('blocks','incoming'),'blocked by');assert.equal(relationCaption('duplicates','incoming'),'duplicated by');assert.equal(relationCaption('relates','both'),'relates to');});
test('comment schema preserves markdown and rejects missing or oversized text',()=>{assert.equal(commentInput({body:'  # Text\n'}).body,'  # Text\n');assert.throws(()=>commentInput({body:''}),{code:'VALIDATION'});assert.throws(()=>commentInput({body:'a'.repeat(100001)}),{code:'VALIDATION'});});

import {h} from 'preact';
import {useState,useEffect} from 'preact/hooks';
import {Notice,Loading,Empty,Field,Button,ConfirmButton,useLoad} from '../../components/ui.jsx';
import {renderMarkdown} from '../../../../shared/src/markdown.js';
import {RELATION_KINDS,relationCaption} from '../../../../shared/src/schemas/discussion.js';
import {mergeIssuePages} from './issue-state.js';
export function Markdown({source}) {
  return <div className="markdown-content" dangerouslySetInnerHTML={{__html:renderMarkdown(source)}}/>;
}
export function insertMention(body,user) {
  const prefix=body&&!/\s$/.test(body)?body+' ':body;
  return prefix+'@['+user.name.replaceAll(']','')+'](user:'+user.userId+') ';
}
export function CommentComposer({members=[],initial='',onSave,onCancel,label='Post comment'}) {
  const [body,setBody]=useState(initial);
  const [preview,setPreview]=useState(false);
  const [error,setError]=useState(null);
  const [busy,setBusy]=useState(false);
  async function submit(event) {
    event.preventDefault();setError(null);setBusy(true);
    try{await onSave({body});setBody('');}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  return <form onSubmit={submit} className="comment-composer">
    <Notice error={error}/>
    <Field label="Comment" error={error?.details?.body}><textarea name="body" rows="5" value={body} maxLength={100000} required onInput={event=>setBody(event.currentTarget.value)} placeholder="Discuss this issue. Markdown and @mentions are supported."/></Field>
    <div className="actions"><Field label="Mention a person"><select value="" onChange={event=>{const member=members.find(item=>item.userId===event.currentTarget.value);if(member)setBody(previous=>insertMention(previous,member));}}><option value="">Choose a person…</option>{members.map(member=><option key={member.userId} value={member.userId}>{member.name}</option>)}</select></Field><Button type="button" onClick={()=>setPreview(value=>!value)}>{preview?'Hide preview':'Preview Markdown'}</Button></div>
    {preview&&<section aria-label="Comment preview"><Markdown source={body}/></section>}
    <p className="field-help">Raw HTML is escaped. Mentions notify people who can read this project.</p>
    <div className="actions"><Button busy={busy} disabled={!body.trim()}>{label}</Button>{onCancel&&<Button type="button" onClick={onCancel} disabled={busy}>Cancel</Button>}</div>
  </form>;
}
function Comment({comment,api,user,canAdmin,members,onChange,readOnly}) {
  const [editing,setEditing]=useState(false);
  const [error,setError]=useState(null);
  const editable=!readOnly&&(comment.authorId===user.id||canAdmin);
  async function remove(){try{await api.delete('/comments/'+comment.id);onChange();}catch(error){setError(error);}}
  return <article className="issue-comment" id={'comment-'+comment.id}>
    <header><strong>{comment.author.name}</strong><time dateTime={comment.createdAt}>{new Date(comment.createdAt).toLocaleString()}</time>{comment.updatedAt!==comment.createdAt&&<span>edited</span>}</header>
    <Notice error={error}/>
    {editing?<CommentComposer initial={comment.body} members={members} label="Save comment" onCancel={()=>setEditing(false)} onSave={async body=>{await api.patch('/comments/'+comment.id,body);setEditing(false);onChange();}}/>:<Markdown source={comment.body}/>}
    {editable&&!editing&&<div className="actions"><Button onClick={()=>setEditing(true)}>Edit comment</Button><ConfirmButton message="Delete this comment?" onConfirm={remove}>Delete comment</ConfirmButton></div>}
  </article>;
}
export function IssueComments({issue,api,user,members,canAdmin}) {
  const result=useLoad(()=>api.get('/issues/'+issue.id+'/comments'),[issue.id]);
  const [comments,setComments]=useState([]);
  const [cursor,setCursor]=useState(null);
  const [error,setError]=useState(null);
  const [busy,setBusy]=useState(false);
  useEffect(()=>{if(result.data){setComments(result.data.items);setCursor(result.data.nextCursor);}},[result.data]);
  async function more(){
    setBusy(true);setError(null);
    try{const page=await api.get('/issues/'+issue.id+'/comments?cursor='+encodeURIComponent(cursor));setComments(previous=>mergeIssuePages(previous,page.items));setCursor(page.nextCursor);}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  return <section aria-label="Issue comments"><h2>Discussion</h2><Notice error={error??result.error}/>
    {result.loading?<Loading/>:comments.length?comments.map(comment=><Comment key={comment.id+comment.updatedAt} {...{comment,api,user,members,canAdmin}} readOnly={issue.archived} onChange={result.reload}/>):<Empty>No comments yet. Start the discussion below.</Empty>}
    {cursor&&<Button busy={busy} onClick={more}>Load more comments</Button>}
    {!issue.archived&&<CommentComposer members={members} onSave={async body=>{await api.post('/issues/'+issue.id+'/comments',body);result.reload();}}/>}
  </section>;
}
export function IssueRelations({issue,issues,api,editable}) {
  const result=useLoad(()=>api.get('/issues/'+issue.id+'/relations'),[issue.id]);
  const [target,setTarget]=useState('');const [kind,setKind]=useState('relates');
  const [error,setError]=useState(null);const [busy,setBusy]=useState(false);
  async function add(event){
    event.preventDefault();setBusy(true);setError(null);
    try{await api.post('/issues/'+issue.id+'/relations',{targetIssueId:target,kind});setTarget('');result.reload();}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  async function remove(relation){try{await api.delete('/relations/'+relation.id);result.reload();}catch(error){setError(error);}}
  return <section aria-label="Issue relations"><h2>Related issues</h2><Notice error={error??result.error}/>
    {result.loading?<Loading/>:result.data?.items.length?<ul>{result.data.items.map(relation=><li key={relation.id}><span>{relation.caption} </span><a href={'#/issues/'+relation.relatedIssue.id}>{relation.relatedIssue.key} · {relation.relatedIssue.title}</a>{editable&&<ConfirmButton message="Remove this relation?" onConfirm={()=>remove(relation)}>Remove relation</ConfirmButton>}</li>)}</ul>:<Empty>No related issues.</Empty>}
    {editable&&<form className="relation-form" onSubmit={add}>
      <Field label="Relation"><select value={kind} onChange={event=>setKind(event.currentTarget.value)}>{RELATION_KINDS.map(value=><option key={value} value={value}>{relationCaption(value,'outgoing')}</option>)}</select></Field>
      <Field label="Related issue" error={error?.details?.targetIssueId}><input required list={'issues-'+issue.id} value={target} onInput={event=>setTarget(event.currentTarget.value)} placeholder="Select or paste an issue ID"/><datalist id={'issues-'+issue.id}>{issues.filter(item=>item.id!==issue.id).map(item=><option key={item.id} value={item.id}>{item.key} · {item.title}</option>)}</datalist></Field>
      <Button busy={busy}>Add relation</Button>
    </form>}
  </section>;
}

import {Markdown,IssueComments,IssueRelations} from './issue-discussion.jsx';
import '../../styles/issues.css';
import {h} from 'preact';
import {useState,useEffect} from 'preact/hooks';
import {Page,Notice,Loading,Empty,Button,Field,useLoad,ConfirmButton} from '../../components/ui.jsx';
import {priorityLabel,PRIORITIES} from '../../../../shared/src/schemas/issue.js';
import {IssueEditor} from './issue-editor.jsx';
import {issueListFilters,mergeIssuePages,relativeDue} from './issue-state.js';
export async function loadIssueContext(api,projectId) {
  const {project,permissions}=await api.get('/projects/'+projectId);
  const [members,labels,issues]=await Promise.all([
    api.get('/orgs/'+project.orgId+'/members?limit=200'),
    api.get('/projects/'+projectId+'/labels?limit=200'),
    api.get('/projects/'+projectId+'/issues?limit=200')
  ]);
  return {project,permissions,members:members.items,labels:labels.items,issues:issues.items};
}
function canEdit(context,user) {
  return !context.project.archived&&context.permissions.write;
}
export function IssueSummary({issue}) {
  const due=relativeDue(issue.dueDate);
  return <article className="issue-summary">
    <div><a href={'#/issues/'+issue.id}><strong>{issue.key}</strong> {issue.title}</a><p>{issue.statusName} · {priorityLabel(issue.priority)} · {issue.assignee?.name??'Unassigned'}</p></div>
    <div className="issue-tags">{issue.labels.map(label=><span key={label.id} className="label-chip" style={{borderColor:label.color}}>{label.name}</span>)}{issue.estimate!==null&&<span>{issue.estimate} points</span>}{issue.dueDate&&<span className={due.overdue?'overdue':''}>{due.label}</span>}</div>
  </article>;
}
export function Issues({params,api,navigate,user}) {
  const context=useLoad(()=>loadIssueContext(api,params.projectId),[params.projectId]);
  const [filters,setFilters]=useState({});
  const [creating,setCreating]=useState(false);
  const [items,setItems]=useState([]);
  const [cursor,setCursor]=useState(null);
  const [error,setError]=useState(null);
  const [busy,setBusy]=useState(false);
  const serialized=JSON.stringify(issueListFilters(filters));
  const results=useLoad(()=>api.get('/projects/'+params.projectId+'/issues?'+new URLSearchParams(JSON.parse(serialized))),[params.projectId,serialized]);
  useEffect(()=>{if(results.data){setItems(results.data.items);setCursor(results.data.nextCursor);}},[results.data]);
  function filter(field,value){setFilters(previous=>({...previous,[field]:value}));}
  async function more(){
    setBusy(true);setError(null);
    try{const page=await api.get('/projects/'+params.projectId+'/issues?'+new URLSearchParams({...issueListFilters(filters),cursor}));setItems(previous=>mergeIssuePages(previous,page.items));setCursor(page.nextCursor);}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  if(context.loading)return <Loading/>;
  if(context.error)return <Notice error={context.error}/>;
  const {project,members,labels}=context.data;
  const editable=canEdit(context.data,user);
  return <Page title={project.key+' issues'} actions={<><a href={'#/projects/'+project.id}>Project</a><a href={'#/projects/'+project.id+'/board'}>Board</a><a href={'#/projects/'+project.id+'/labels'}>Labels</a>{editable&&<Button onClick={()=>setCreating(true)}>New issue</Button>}</>}>
    <Notice error={error??results.error}/>
    {project.archived&&<Notice>This project is archived and read-only.</Notice>}
    {creating&&<IssueEditor {...context.data} onCancel={()=>setCreating(false)} onSave={async body=>{const {issue}=await api.post('/projects/'+project.id+'/issues',body);navigate('/issues/'+issue.id);}}/>}
    <div className="issue-filters" role="search" aria-label="Filter issues">
      <Field label="Search issues" name="q" type="search" value={filters.q??''} onInput={event=>filter('q',event.currentTarget.value)}/>
      <Field label="Status"><select value={filters.statusId??''} onChange={event=>filter('statusId',event.currentTarget.value)}><option value="">All statuses</option>{project.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
      <Field label="Assignee"><select value={filters.assigneeId??''} onChange={event=>filter('assigneeId',event.currentTarget.value)}><option value="">Anyone</option>{members.map(member=><option key={member.userId} value={member.userId}>{member.name}</option>)}</select></Field>
      <Field label="Label"><select value={filters.labelId??''} onChange={event=>filter('labelId',event.currentTarget.value)}><option value="">All labels</option>{labels.map(label=><option key={label.id} value={label.id}>{label.name}</option>)}</select></Field>
      <Field label="Priority"><select value={filters.priority??''} onChange={event=>filter('priority',event.currentTarget.value)}><option value="">All priorities</option>{PRIORITIES.map(priority=><option key={priority.value} value={priority.value}>{priority.label}</option>)}</select></Field>
      <Button type="button" onClick={()=>setFilters({})}>Clear filters</Button>
    </div>
    {results.loading?<Loading/>:items.length?<div className="issue-list">{items.map(issue=><IssueSummary key={issue.id} issue={issue}/>)}</div>:<Empty>No issues match these filters.</Empty>}
    {cursor&&<Button busy={busy} onClick={more}>Load more issues</Button>}
  </Page>;
}
export function IssueDetail({params,api,navigate,user}) {
  const [editing,setEditing]=useState(false);
  const [error,setError]=useState(null);
  const result=useLoad(async()=>{
    const {issue}=await api.get('/issues/'+params.issueId);
    return {issue,...await loadIssueContext(api,issue.projectId)};
  },[params.issueId]);
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const {issue,issues}=result.data;
  const editable=canEdit(result.data,user);
  const parent=issues.find(item=>item.id===issue.parentId);
  const children=issues.filter(item=>item.parentId===issue.id);
  const due=relativeDue(issue.dueDate);
  async function remove(){
    try{await api.delete('/issues/'+issue.id);navigate('/projects/'+issue.projectId+'/issues');}catch(error){setError(error);}
  }
  return <Page title={issue.key+' · '+issue.title} actions={<><a href={'#/projects/'+issue.projectId+'/issues'}>All issues</a>{editable&&<Button onClick={()=>setEditing(value=>!value)}>{editing?'Close editor':'Edit issue'}</Button>}</>}>
    <Notice error={error}/>
    {editing?<IssueEditor key={issue.updatedAt} {...result.data} onCancel={()=>setEditing(false)} onSave={async body=>{await api.patch('/issues/'+issue.id,body);setEditing(false);result.reload();}}/>:<>
      <section aria-label="Description"><h2>Description</h2><Markdown source={issue.description||'No description yet.'}/></section>
      <dl className="issue-properties"><dt>Status</dt><dd>{issue.statusName}</dd><dt>Priority</dt><dd>{priorityLabel(issue.priority)}</dd><dt>Assignee</dt><dd>{issue.assignee?.name??'Unassigned'}</dd><dt>Estimate</dt><dd>{issue.estimate??'Not estimated'}</dd><dt>Due</dt><dd className={due.overdue?'overdue':''}>{due.label}</dd><dt>Created by</dt><dd>{issue.creator.name}</dd><dt>Created</dt><dd><time dateTime={issue.createdAt}>{new Date(issue.createdAt).toLocaleString()}</time></dd><dt>Updated</dt><dd><time dateTime={issue.updatedAt}>{new Date(issue.updatedAt).toLocaleString()}</time></dd><dt>Parent</dt><dd>{parent?<a href={'#/issues/'+parent.id}>{parent.key} · {parent.title}</a>:'No parent issue'}</dd></dl>
      <section><h2>Labels</h2>{issue.labels.length?issue.labels.map(label=><span className="label-chip" key={label.id} style={{borderColor:label.color}}>{label.name}</span>):<Empty>No labels assigned.</Empty>}</section>
      {children.length>0&&<section><h2>Child issues</h2>{children.map(child=><IssueSummary key={child.id} issue={child}/>)}</section>}
      <IssueRelations issue={issue} issues={issues} api={api} editable={editable}/><IssueComments issue={{...issue,archived:result.data.project.archived}} api={api} user={user} members={result.data.members} canAdmin={result.data.permissions.manage}/>{editable&&<div className="danger-zone"><ConfirmButton message={'Delete '+issue.key+' permanently?'} onConfirm={remove}>Delete issue</ConfirmButton></div>}
    </>}
  </Page>;
}
export function ProjectLabels({params,api,user}) {
  const result=useLoad(()=>loadIssueContext(api,params.projectId),[params.projectId]);
  const [name,setName]=useState('');const [color,setColor]=useState('#5965d8');
  const [editing,setEditing]=useState(null);const [error,setError]=useState(null);const [busy,setBusy]=useState(false);
  async function save(event){
    event.preventDefault();setBusy(true);setError(null);
    try{if(editing)await api.patch('/labels/'+editing,{name,color});else await api.post('/projects/'+params.projectId+'/labels',{name,color});setEditing(null);setName('');result.reload();}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  async function remove(label){try{await api.delete('/labels/'+label.id);result.reload();}catch(error){setError(error);}}
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const editable=canEdit(result.data,user);
  return <Page title={result.data.project.key+' labels'} actions={<a href={'#/projects/'+params.projectId+'/issues'}>Issues</a>}>
    <Notice error={error}/>
    {editable&&<form onSubmit={save}><Field label="Label name" name="name" value={name} required maxLength={60} onInput={event=>setName(event.currentTarget.value)}/><Field label="Color" name="color" type="color" value={color} onInput={event=>setColor(event.currentTarget.value)}/><Button busy={busy}>{editing?'Save label':'Create label'}</Button>{editing&&<Button type="button" onClick={()=>{setEditing(null);setName('');}}>Cancel editing</Button>}</form>}
    {result.data.labels.length?<ul>{result.data.labels.map(label=><li key={label.id}><span className="label-chip" style={{borderColor:label.color}}>{label.name}</span>{editable&&<><Button onClick={()=>{setEditing(label.id);setName(label.name);setColor(label.color);}}>Edit {label.name}</Button><ConfirmButton message={'Remove '+label.name+' from this project and its issues?'} onConfirm={()=>remove(label)}>Delete {label.name}</ConfirmButton></>}</li>)}</ul>:<Empty>No labels yet.</Empty>}
  </Page>;
}
export const issueRoutes=[{path:'/projects/:projectId/issues',component:Issues},{path:'/issues/:issueId',component:IssueDetail},{path:'/projects/:projectId/labels',component:ProjectLabels}];
